impl SettingsEquilibrium {
    /// Read the settings from their XML: that of `equilibrium.xml`, with each file it links to written in its link's place, as
    /// `serialise_python_dataclass_to_imas_parameters_input` writes it.
    ///
    /// Each element is read into the field of the same name. The XML is not checked against its XML schema here, as it was checked before it
    /// was passed in.
    ///
    /// # Errors
    /// The XML is not well-formed, its root element is not `<equilibrium_settings>`, an element is not in the XML schema this was generated
    /// from, is there more than once unless it is repeated, or is required but missing, or a leaf cannot be read as its Rust type
    pub fn from_xml(xml: &str) -> Result<SettingsEquilibrium, String> {
        let document: Document = Document::parse(xml).map_err(|error| format!("the settings are not well-formed XML: {error}"))?;
        let root: Node = document.root_element();
        if root.tag_name().name() != "equilibrium_settings" {
            return Err(format!(
                "the root element of the settings is <{}>, rather than <equilibrium_settings>",
                root.tag_name().name()
            ));
        }

        read_settings_equilibrium(root, "equilibrium_settings")
    }
}

/// Read `SettingsEquilibrium` from its XML element, whose path is `path`
fn read_settings_equilibrium(node: Node<'_, '_>, path: &str) -> Result<SettingsEquilibrium, String> {
    let mut timeslices: Option<SettingsEquilibriumTimeslices> = None;
    let mut numerics: Option<SettingsEquilibriumNumerics> = None;
    let mut grid: Option<SettingsEquilibriumGrid> = None;
    let mut initial_guess: Option<SettingsEquilibriumInitialGuess> = None;
    let mut source_function_p_prime: Option<SettingsEquilibriumSourceFunctionPPrime> = None;
    let mut source_function_ff_prime: Option<SettingsEquilibriumSourceFunctionFfPrime> = None;
    let mut pf_passive_dof: Option<SettingsEquilibriumPfPassiveDof> = None;
    let mut constraints: Option<SettingsEquilibriumEquilibriumConstraints> = None;
    for child in child_elements(node, path)? {
        let child_name: &str = child.tag_name().name();
        let child_path: String = format!("{path}/{child_name}");
        match child_name {
            "timeslices" => {
                if timeslices.is_some() {
                    return Err(repeated_element(&child_path));
                }
                timeslices = Some(read_settings_equilibrium_timeslices(child, &child_path)?);
            }
            "numerics" => {
                if numerics.is_some() {
                    return Err(repeated_element(&child_path));
                }
                numerics = Some(read_settings_equilibrium_numerics(child, &child_path)?);
            }
            "grid" => {
                if grid.is_some() {
                    return Err(repeated_element(&child_path));
                }
                grid = Some(read_settings_equilibrium_grid(child, &child_path)?);
            }
            "initial_guess" => {
                if initial_guess.is_some() {
                    return Err(repeated_element(&child_path));
                }
                initial_guess = Some(read_settings_equilibrium_initial_guess(child, &child_path)?);
            }
            "source_function_p_prime" => {
                if source_function_p_prime.is_some() {
                    return Err(repeated_element(&child_path));
                }
                source_function_p_prime = Some(read_settings_equilibrium_source_function_p_prime(child, &child_path)?);
            }
            "source_function_ff_prime" => {
                if source_function_ff_prime.is_some() {
                    return Err(repeated_element(&child_path));
                }
                source_function_ff_prime = Some(read_settings_equilibrium_source_function_ff_prime(child, &child_path)?);
            }
            "pf_passive_dof" => {
                if pf_passive_dof.is_some() {
                    return Err(repeated_element(&child_path));
                }
                pf_passive_dof = Some(read_settings_equilibrium_pf_passive_dof(child, &child_path)?);
            }
            "constraints" => {
                if constraints.is_some() {
                    return Err(repeated_element(&child_path));
                }
                constraints = Some(read_settings_equilibrium_equilibrium_constraints(child, &child_path)?);
            }
            _ => return Err(unexpected_element(&child_path, GENERATOR_PATH)),
        }
    }

    Ok(SettingsEquilibrium {
        timeslices: timeslices.ok_or_else(|| missing_element(&format!("{path}/timeslices")))?,
        numerics: numerics.ok_or_else(|| missing_element(&format!("{path}/numerics")))?,
        grid: grid.ok_or_else(|| missing_element(&format!("{path}/grid")))?,
        initial_guess: initial_guess.ok_or_else(|| missing_element(&format!("{path}/initial_guess")))?,
        source_function_p_prime: source_function_p_prime.ok_or_else(|| missing_element(&format!("{path}/source_function_p_prime")))?,
        source_function_ff_prime: source_function_ff_prime.ok_or_else(|| missing_element(&format!("{path}/source_function_ff_prime")))?,
        pf_passive_dof: pf_passive_dof.ok_or_else(|| missing_element(&format!("{path}/pf_passive_dof")))?,
        constraints: constraints.ok_or_else(|| missing_element(&format!("{path}/constraints")))?,
    })
}

